    t0 = time.process_time()
    deadline = budget_seconds - 2.0  # margin

    N = 4000
    # Initialize from start (resampled) or a smooth bump.
    if start is not None:
        a = np.asarray(start, dtype=float)
        if a.size != N:
            x = np.linspace(0, 1, a.size)
            xi = np.linspace(0, 1, N)
            a = np.interp(xi, x, a)
        a = np.clip(a, 0, None)
        if a.sum() <= 0:
            a = np.ones(N)
    else:
        x = np.linspace(-1, 1, N)
        a = np.exp(-2.0 * x * x)

    def norm(h):
        m = np.max(h)
        if m <= 0:
            return np.ones(N)
        return h / m

    a = norm(a)
    best = a.copy()
    bestC = _C(best)

    rng = np.random.default_rng(12345)

    # Coordinate-wise multiplicative refinement with shrinking perturbations.
    # Work on a coarse-to-fine grid by parameterizing perturbations as smooth.
    step = 0.5
    while time.process_time() - t0 < deadline:
        improved = False
        # random smooth perturbation directions
        for _ in range(60):
            if time.process_time() - t0 >= deadline:
                break
            k = rng.integers(1, 12)
            x = np.linspace(0, 1, N)
            d = np.sin(2 * np.pi * k * x + rng.uniform(0, 2 * np.pi))
            d += 0.5 * np.sin(2 * np.pi * (k + 3) * x + rng.uniform(0, 2 * np.pi))
            cand = a * np.exp(step * d)
            cand = norm(cand)
            c = _C(cand)
