                a = cand
                bestC = c
                best = cand.copy()
                improved = True
        if not improved:
            step *= 0.6
            if step < 1e-4:
                break

    # Local greedy coordinate polish on a decimated version for speed.
    while time.process_time() - t0 < deadline:
        idxs = rng.permutation(N)[: min(N, 400)]
