    i = np.arange(N, dtype=float)
    u = 2.0 * i / (N - 1) - 1.0
    au = np.abs(u)
    neg = u < 0

    def build(x):
        p, ql, qr = x
        q = np.where(neg, ql, qr)
        base = 1.0 - np.power(au, p)
        base = np.clip(base, 0.0, None)
        return np.power(base, q)

    def obj(x):
        return _C(build(x))

    bounds = [(0.3, 6.0), (0.05, 6.0), (0.05, 6.0)]

    best_h = None
    best_c = np.inf

    # seed with start if available
    if start is not None:
