import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar


def _conv(h):
    n = len(h)
    m = 1
    while m < 2 * n:
        m *= 2
    H = np.fft.rfft(h, m)
    c = np.fft.irfft(H * H, m)[: 2 * n - 1]
    return np.maximum(c, 0)


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * _conv(h).max() / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    N = 30000

    # ---- initialise from start (or a smooth bump) ----
    u = (np.arange(N) + 0.5) / N
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() > 0 and len(s) >= 2:
            xp = np.linspace(0.0, 1.0, len(s))
            h = np.interp(u, xp, s)
        elif s.sum() > 0:
            h = np.full(N, float(s[0]))
        else:
            h = np.cos(np.pi * (u - 0.5)) ** 2 + 1e-6
    else:
        h = np.cos(np.pi * (u - 0.5)) ** 2 + 1e-6
    h = np.maximum(h, 0.0)
    h = h / h.sum()
    best_h = h.copy()
    best_C = _C(best_h)
    print(f"init C={best_C:.6f}")

    # ---- multi-knot active-set gradient step ----
    # gradient of max over near-max knots, g_i = sum_k w_k h_{k-i}
    # then line-search h *= exp(-t*d).  Use progressively tighter w band.
    for band in [0.999, 0.9995, 0.9998, 0.9999]:
        if time.process_time() > deadline:
            break
        for _ in range(60):
            if time.process_time() > deadline:
                break
            c = _conv(h)
            cmax = c.max()
            idx = np.where(c >= cmax * band)[0]
            if len(idx) == 0:
                break
            g = np.zeros(N)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                ii = np.arange(lo, hi + 1)
                g[ii] += h[k - ii]
            g /= len(idx)
            gmax = g.max()
            if gmax <= 0:
                break
            d = g / gmax

            C0 = _C(h)

            def phi(t):
                hh = h * np.exp(-t * d)
                ss = hh.sum()
                if ss <= 0:
                    return np.inf
                return _C(hh / ss)

            try:
                res = minimize_scalar(phi, bounds=(0.0, 3.0), method='bounded',
                                      options={'xatol': 1e-5})
                t_opt, C_opt = res.x, res.fun
            except Exception:
                t_opt, C_opt = 0.0, C0

            if C_opt < C0 - 1e-12:
                hh = h * np.exp(-t_opt * d)
                h = hh / hh.sum()
                Cv = _C(h)
                if Cv < best_C:
                    best_C = Cv
                    best_h = h.copy()
            else:
                h = best_h.copy()
                break
        if time.process_time() > deadline:
            break
        h = best_h.copy()
    print(f"stage-grad C={best_C:.6f}, cpu={time.process_time()-t0:.2f}s")

    # ---- fine local coordinate line searches on blocks of h ----
    h = best_h.copy()
    blocks = [512, 256, 128, 64, 32, 16, 8]
    gr = (np.sqrt(5.0) - 1.0) / 2.0

    def golden_C(hbase, idx, lo, hi, tol=1e-5):
        a, b = lo, hi
        c_ = b - gr * (b - a)
        d_ = a + gr * (b - a)

        def evalC(s):
            hh = hbase.copy()
            hh[idx] *= np.exp(s)
            ss = hh.sum()
            if ss <= 0:
                return np.inf
            return _C(hh / ss)

        fc = evalC(c_)
        fd = evalC(d_)
        while (b - a) > tol:
            if fc < fd:
                b, d_, fd = d_, c_, fc
                c_ = b - gr * (b - a)
                fc = evalC(c_)
            else:
                a, c_, fc = c_, d_, fd
                d_ = a + gr * (b - a)
                fd = evalC(d_)
        s = 0.5 * (a + b)
        return s, evalC(s)

    while time.process_time() < deadline:
        c = _conv(h)
        cmax = c.max()
        if cmax <= 0:
            break
        sel = np.where(c >= 0.995 * cmax)[0]
        if len(sel) == 0:
            break
        improved_any = False
        for B in blocks:
            if time.process_time() > deadline:
                break
            for st in range(0, len(sel), B):
                if time.process_time() > deadline:
                    break
                blk = sel[st:st + B]
                if len(blk) == 0:
                    continue
                idx = np.clip(blk, 0, N - 1)
                idx = np.unique(idx)
                if len(idx) == 0:
                    continue
                C0 = _C(h)
                s_opt, C_opt = golden_C(h, idx, -0.4, 0.4)
                if C_opt < C0 - 1e-13:
                    hh = h.copy()
                    hh[idx] *= np.exp(s_opt)
                    h = hh / hh.sum()
                    Cv = _C(h)
                    if Cv < best_C:
                        best_C = Cv
                        best_h = h.copy()
                        improved_any = True
        if not improved_any:
            break

    print(f"final C={best_C:.6f}, N={len(best_h)}, cpu={time.process_time()-t0:.2f}s")
    return np.asarray(best_h, dtype=float)

