import numpy as np
import time
from scipy.optimize import minimize


def _make_M(N):
    M = 1
    while M < 3 * N:
        M *= 2
    return M


def _conv(h, M=None):
    n = len(h)
    if M is None:
        M = _make_M(n)
    H = np.fft.rfft(h, M)
    c = np.fft.irfft(H * H, M)[:2 * n - 1]
    return np.maximum(c, 0)


def _C(h, M=None):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * _conv(h, M).max() / (s * s)


def _golden(f, a, b, iters=40):
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    c1 = b - gr * (b - a)
    d1 = a + gr * (b - a)
    f1 = f(c1)
    f2 = f(d1)
    for _ in range(iters):
        if f1 < f2:
            b, d1, f2 = d1, c1, f1
            c1 = b - gr * (b - a)
            f1 = f(c1)
        else:
            a, c1, f1 = c1, d1, f2
            d1 = a + gr * (b - a)
            f2 = f(d1)
    return (a + b) / 2.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    N = 23750
    u = (np.arange(N) + 0.5) / N

    h = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.sum() > 0 and len(s) >= 2:
            if len(s) == N:
                h = s.copy()
            else:
                xp = (np.arange(len(s)) + 0.5) / len(s)
                h = np.interp(u, xp, s)
            h = np.maximum(h, 0.0)
            if h.sum() > 0:
                h = h / h.sum()
            else:
                h = None
    if h is None:
        h = np.cos(np.pi * (u - 0.5)) ** 2 + 1e-6
        h = h / h.sum()

    M = _make_M(N)

    best_h = h.copy()
    best_C = _C(best_h, M)
    print(f"start C={best_C:.10f} N={N}")

    # ---- Phase 7: pairwise additive mass transfers + block golden polish ----
    rng = np.random.RandomState(987654321)
    h = best_h.copy()

    def block_golden_sweep(h, best_C, best_h):
        block_sizes6 = [64, 32, 16, 8, 4, 2, 1]
        any_improved = False
        for B in block_sizes6:
            stride = max(1, B // 2)
            for st in range(0, N, stride):
                if time.process_time() >= deadline:
                    return h, best_C, best_h, any_improved
                en = min(N, st + B)
                if en <= st:
                    continue
                cur_C = _C(h, M)

                def f(t, h=h, st=st, en=en):
                    hn = h.copy()
                    hn[st:en] *= np.exp(t)
                    s = hn.sum()
                    if s <= 0:
                        return np.inf
                    return _C(hn / s, M)

                tt = _golden(f, -0.05, 0.05, iters=30)
                ft = f(tt)
                if ft < cur_C - 1e-15:
                    h[st:en] *= np.exp(tt)
                    s = h.sum()
                    if s > 0:
                        h /= s
                        any_improved = True
                        if ft < best_C:
                            best_C = ft
                            best_h = h.copy()
        return h, best_C, best_h, any_improved

    sweep = 0
    while time.process_time() < deadline:
        sweep += 1
        any_improved = False
        perm = rng.permutation(N - 1)
        for i in perm:
            if time.process_time() >= deadline:
                break
            i = int(i)
            cur_C = _C(h, M)

            def f(t, h=h, i=i):
                hn = h.copy()
                hn[i] += t
                hn[i + 1] -= t
                if hn[i] < 0 or hn[i + 1] < 0:
                    return np.inf
                s = hn.sum()
                if s <= 0:
                    return np.inf
                return _C(hn / s, M)

            tt = _golden(f, -0.02, 0.02, iters=30)
            ft = f(tt)
            if ft < cur_C - 1e-16:
                h[i] += tt
                h[i + 1] -= tt
                s = h.sum()
                if s > 0:
                    h /= s
                    any_improved = True
                    if ft < best_C:
                        best_C = ft
                        best_h = h.copy()

        # one constant-block exact golden sweep after each full permutation
        h, best_C, best_h, blk_improved = block_golden_sweep(h, best_C, best_h)
        any_improved = any_improved or blk_improved

        print(f"psweep={sweep} C={best_C:.10f} cpu={time.process_time()-t0:.2f}s")
        if not any_improved:
            break

    print(f"final C={best_C:.10f}, N={len(best_h)}, cpu={time.process_time()-t0:.2f}s")
    return np.asarray(best_h, dtype=float)
